/// <summary>
/// PricingAttribute of table <c>InventDim</c> field InventSiteId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimInventSiteId extends GUPPricingAttributeInventDim implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventSiteId);
}

    public Set getAllowedValues()
    {
        var       ret = new Set(Types::String);
        InventDim inventDim;

        while select inventDim
            group by InventSiteId
        {
            if (! ret.in(inventDim.InventSiteId))
            {
                ret.add(inventDim.InventSiteId);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(InventDim, InventSiteId));
        qbr.value(queryValue(_value));
    }
